@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>Recipe Categories - RecipeHub</PageTitle>

<h1>Browse Recipes</h1>
<p class="lead">Choose a category to explore delicious recipes from our community.</p>

<div class="row g-4 mt-2">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-4 col-sm-6">
            <div class="card h-100 shadow-sm category-card">
                <div class="card-body text-center">
