                        <span class="category-icon">@GetCategoryIcon(category)</span>
                    </h3>
                    <h4>@category</h4>
                    <p class="text-muted">@RecipeService.GetRecipesByCategory(category).Count recipes</p>
                    <a href="/recipes/category/@category.ToLowerInvariant()" class="btn btn-outline-primary">
                        Browse @category
                    </a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string GetCategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Asian" => "🥢",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}
"}

