        var avg = _ratings[recipeId].Average();
        return (Math.Round(avg, 1), _ratings[recipeId].Count);
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= (_userRating ?? 0) ? "filled" : (star <= (int)Math.Round(AverageRating) ? "average" : ""))"
                  @onclick="() => Rate(star)"
                  title="Rate @star star(s)">
                ★
            </span>
        }
    </div>
    <span class="rating-text">
        @if (_userRating.HasValue)
        {
            <text>You rated @_userRating stars!</text>
        }
        else
        {
            <text>@AverageRating.ToString("0.0") (@RatingCount ratings)</text>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    [Inject] private Services.RecipeService RecipeService { get; set; } = default!;

    private int? _userRating;

    private void Rate(int stars)
    {
        _userRating = stars;
        var (avg, count) = RecipeService.SubmitRating(RecipeId, stars);
        AverageRating = avg;
        RatingCount = count;
    }
}

