toolArgs.file_text:
@page "/recipes"

@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>Recipe Categories - RecipeHub</PageTitle>

<h1>Browse Recipes</h1>
<p class="lead">Choose a category to explore delicious recipes from our community.</p>

<div class="row g-4 mt-2">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-4 col-sm-6">
            <div class="card h-100 shadow-sm category-card">
                <div class="card-body text-center">
                    <h3 class="card-title">
                        <span class="category-icon">@GetCategoryIcon(category)</span>
                    </h3>
                    <h4>@category</h4>
                    <p class="text-muted">@RecipeService.GetRecipesByCategory(category).Count recipes</p>
                    <a href="/recipes/category/@category.ToLowerInvariant()" class="btn btn-outline-primary">
                        Browse @category
                    </a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string GetCategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Asian" => "🥢",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

@page "/recipes/category/{CategoryName}"

@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/recipes">All Categories</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (_recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row g-4 mt-2">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">@recipe.Description</p>
                        <div class="d-flex justify-content-between align-items-center">
                            <span class="text-warning">
                                @for (int i = 0; i < (int)Math.Round(recipe.AverageRating); i++)
                                {
                                    <text>★</text>
                                }
                                <small class="text-muted">(@recipe.AverageRating.ToString("0.0"))</small>
                            </span>
                            <a href="/recipes/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                        </div>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<RecipeHub.Models.Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipes/{RecipeId:int}"

@inject RecipeHub.Services.RecipeService RecipeService

@if (_recipe is null)
{
    <PageTitle>Recipe Not Found - RecipeHub</PageTitle>
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <PageTitle>@_recipe.Title - RecipeHub</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/recipes">All Categories</a></li>
            <li class="breadcrumb-item"><a href="/recipes/category/@_recipe.Category.ToLowerInvariant()">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        </ol>
    </nav>

    <h1>@_recipe.Title</h1>
    <p class="lead">@_recipe.Description</p>

    <div class="mb-4">
        <h5>Rate this recipe</h5>
        <RecipeHub.Components.Pages.Recipes.StarRating
            RecipeId="@_recipe.Id"
            AverageRating="@_recipe.AverageRating"
            RatingCount="@_recipe.RatingCount" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in _recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <div class="card mb-4">
                <div class="card-header"><h5 class="mb-0">Instructions</h5></div>
                <div class="card-body">
                    <ol class="mb-0">
                        @foreach (var step in _recipe.Steps)
                        {
                            <li class="mb-2">@step</li>
                        }
                    </ol>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int RecipeId { get; set; }

    private RecipeHub.Models.Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetRecipeById(RecipeId);
    }
}

@page "/submit"
@rendermode InteractiveServer

@inject RecipeHub.Services.RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p class="lead">Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Thank you for sharing "<strong>@_submission.Title</strong>" with the community.</p>
        <a href="/recipes" class="btn btn-primary">Browse Recipes</a>
    </div>
}
else
{
    <EditForm Model="_submission" OnValidSubmit="HandleSubmit" class="mt-4" FormName="submit-recipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_submission.Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_submission.Category">
                <option value="">Select a category...</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Asian">Asian</option>
                <option value="Mexican">Mexican</option>
                <option value="Desserts">Desserts</option>
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="_submission.Ingredients"
                           placeholder="Enter one ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <div class="form-text">Enter one ingredient per line.</div>
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="8" @bind-Value="_submission.Steps"
                           placeholder="Enter one step per line&#10;e.g.,&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
            <div class="form-text">Enter one step per line.</div>
        </div>

        <button type="submit" class="btn btn-primary btn-lg"
                disabled="@(string.IsNullOrWhiteSpace(_submission.Title) || string.IsNullOrWhiteSpace(_submission.Category))">
            Submit Recipe
        </button>
    </EditForm>
}

@code {
    private RecipeHub.Models.RecipeSubmission _submission = new();
    private bool _submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_submission.Title) || string.IsNullOrWhiteSpace(_submission.Category))
            return;

        RecipeService.AddRecipe(_submission);
        _submitted = true;
    }
}

