namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple and delicious pizza with fresh mozzarella, tomatoes, and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps =
            [
                "Preheat oven to 475°F (245°C).",
                "Roll out pizza dough on a floured surface.",
                "Spread crushed tomatoes evenly over the dough.",
                "Tear mozzarella into pieces and distribute over the sauce.",
                "Bake for 10-12 minutes until crust is golden.",
                "Top with fresh basil and a drizzle of olive oil."
            ],
            AverageRating = 4.5, RatingCount = 24
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Creamy pasta with pancetta, eggs, and Parmesan cheese.",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Parmesan cheese", "Black pepper", "Salt"],
            Steps =
            [
                "Cook spaghetti in salted boiling water until al dente.",
                "Fry pancetta until crispy.",
                "Whisk eggs with grated Parmesan and pepper.",
                "Toss hot pasta with pancetta, then quickly stir in the egg mixture.",
                "Serve immediately with extra Parmesan."
            ],
            AverageRating = 4.7, RatingCount = 31
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken pieces in a rich, spiced tomato cream sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps =
            [
                "Marinate chicken in yogurt and spices for at least 1 hour.",
                "Grill or broil chicken until charred.",
                "Sauté onion, garlic, and ginger in a pan.",
                "Add tomato sauce and spices; simmer 15 minutes.",
                "Stir in cream and add chicken pieces.",
                "Simmer 10 more minutes and serve with rice."
            ],
            AverageRating = 4.8, RatingCount = 42
        },
        new()
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
            Description = "Stir-fried rice noodles with vegetables, tofu, and a tangy sauce.",
            Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Carrots", "Green onions", "Peanuts", "Lime", "Soy sauce", "Tamarind paste"],
            Steps =
            [
                "Soak rice noodles in warm water for 20 minutes.",
                "Press and cube tofu, then pan-fry until golden.",
                "Stir-fry vegetables in a wok over high heat.",
                "Mix soy sauce, tamarind paste, and lime juice for the sauce.",
                "Add noodles and sauce to the wok; toss to combine.",
                "Top with peanuts, bean sprouts, and lime wedges."
            ],
            AverageRating = 4.3, RatingCount = 18
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in crispy tortillas with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomatoes", "Cheddar cheese", "Sour cream", "Salsa"],
            Steps =
            [
                "Brown ground beef in a skillet over medium-high heat.",
                "Add taco seasoning and water; simmer until thickened.",
                "Warm tortillas in a dry pan or oven.",
                "Fill tortillas with seasoned beef.",
                "Top with lettuce, tomatoes, cheese, sour cream, and salsa."
            ],
            AverageRating = 4.2, RatingCount = 27
        },
        new()
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich chocolate cakes with a molten center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps =
            [
                "Preheat oven to 425°F (220°C). Grease ramekins.",
                "Melt chocolate and butter together.",
                "Whisk eggs and sugar until thick; fold into chocolate mixture.",
                "Add flour and vanilla; mix gently.",
                "Pour into ramekins and bake 12-14 minutes.",
                "Invert onto plates and serve immediately."
            ],
            AverageRating = 4.9, RatingCount = 55
        },
        new()
        {
            Id = 7, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh avocado dip with lime, cilantro, and jalapeño.",
            Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
            Steps =
            [
                "Halve and pit avocados; scoop into a bowl.",
                "Mash with a fork to desired consistency.",
                "Stir in diced onion, tomato, jalapeño, and cilantro.",
                "Add lime juice and salt to taste.",
                "Serve immediately with tortilla chips."
            ],
            AverageRating = 4.6, RatingCount = 33
        },
        new()
        {
            Id = 8, Title = "Miso Ramen", Category = "Asian",
            Description = "Hearty Japanese noodle soup with a rich miso broth.",
            Ingredients = ["Ramen noodles", "Miso paste", "Chicken broth", "Soy sauce", "Soft-boiled egg", "Green onions", "Corn", "Nori", "Sesame oil"],
            Steps =
            [
                "Bring chicken broth to a simmer.",
                "Whisk in miso paste and soy sauce.",
                "Cook ramen noodles according to package directions.",
                "Place noodles in bowls; ladle broth over them.",
                "Top with halved soft-boiled egg, corn, green onions, and nori.",
                "Drizzle with sesame oil before serving."
            ],
            AverageRating = 4.4, RatingCount = 20
        }
    ];

    private readonly Dictionary<int, List<int>> _ratings = new();

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1,
            Title = submission.Title,
            Category = submission.Category,
            Description = $"A community-submitted {submission.Category.ToLowerInvariant()} recipe.",
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        };
        _recipes.Add(recipe);
    }

    public (double average, int count) SubmitRating(int recipeId, int stars)
    {
        stars = Math.Clamp(stars, 1, 5);
        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = [];
        _ratings[recipeId].Add(stars);

        var recipe = GetRecipeById(recipeId);
        if (recipe is not null)
        {
            var allRatings = _ratings[recipeId];
            var totalRatings = recipe.RatingCount + allRatings.Count;
            recipe.AverageRating = Math.Round(
                (recipe.AverageRating * recipe.RatingCount + allRatings.Sum()) / totalRatings, 1);
        }

        var avg = _ratings[recipeId].Average();
        return (Math.Round(avg, 1), _ratings[recipeId].Count);
    }
}

